function selectCampaigns(campaigns, maxSpend) {
  const isBetter = (a,b) => { // a better than b
    if (!b) return true;
    if (a.signups !== b.signups) return a.signups > b.signups;
    if (a.spend !== b.spend) return a.spend < b.spend;
    const aStr = a.ids.join(',');
    const bStr = b.ids.join(',');
    return aStr < bStr;
  };

  let dp = new Map();
  dp.set(0, {signups:0, spend:0, ids: []});

  for (const camp of campaigns) {
    const spend = camp.dailySpend;
    const signups = camp.expectedSignups;
    const id = camp.id;
    const newEntries = new Map();
    for (const [curSpend, state] of dp.entries()) {
      const newSpend = curSpend + spend;
      if (newSpend > maxSpend) continue;
      const newSignups = state.signups + signups;
      // merge ids sorted
      const newIds = insertSorted(state.ids, id);
      const existing = dp.get(newSpend) || newEntries.get(newSpend);
      const candidate = {signups:newSignups, spend:newSpend, ids:newIds};
      if (isBetter(candidate, existing)) {
        newEntries.set(newSpend, candidate);
      }
    }
    // merge newEntries into dp, keeping best per spend
    for (const [s, cand] of newEntries.entries()) {
      const cur = dp.get(s);
      if (isBetter(cand, cur)) dp.set(s, cand);
    }
  }

  // find best overall
  let best = null;
  for (const state of dp.values()) {
    if (isBetter(state, best)) best = state;
  }
  return best ? best.ids : [];
}

